-- READ-ONLY exact-key and nearest 300-second target check for legacy rows in existing gap windows.
SELECT o.gap_id, COUNT(*) AS old_source_rows, SUM(w.`dateTime` IS NOT NULL) AS exact_wh1080_matches, SUM(z.`dateTime` IS NOT NULL) AS exact_eu_old_matches, SUM(r.`dateTime` IS NOT NULL) AS exact_reconstruction_matches, SUM(MOD(o.`dateTime`,300)=0) AS on_300s_grid, SUM(MOD(o.`dateTime`,300)<>0) AS off_300s_grid, COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS distinct_nearest_300s_slots, COUNT(*)-COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS source_projection_collisions, SUM(rp.`dateTime` IS NOT NULL) AS rows_projecting_to_occupied_reconstruction_slots, SUM(NOT (o.`outTemp` <=> w.`outTemp`)) AS outTemp_old_wh_conflicts, SUM(NOT (o.`outTemp` <=> z.`outTemp`)) AS outTemp_old_euold_conflicts, SUM(NOT (o.`outHumidity` <=> w.`outHumidity`)) AS outHumidity_old_wh_conflicts, SUM(NOT (o.`outHumidity` <=> z.`outHumidity`)) AS outHumidity_old_euold_conflicts, SUM(NOT (o.`rain` <=> w.`rain`)) AS rain_old_wh_conflicts, SUM(NOT (o.`rain` <=> z.`rain`)) AS rain_old_euold_conflicts, SUM(NOT (o.`rainRate` <=> w.`rainRate`)) AS rainRate_old_wh_conflicts, SUM(NOT (o.`rainRate` <=> z.`rainRate`)) AS rainRate_old_euold_conflicts, SUM(NOT (o.`windSpeed` <=> w.`windSpeed`)) AS windSpeed_old_wh_conflicts, SUM(NOT (o.`windSpeed` <=> z.`windSpeed`)) AS windSpeed_old_euold_conflicts, SUM(NOT (o.`windGust` <=> w.`windGust`)) AS windGust_old_wh_conflicts, SUM(NOT (o.`windGust` <=> z.`windGust`)) AS windGust_old_euold_conflicts, SUM(NOT (o.`windDir` <=> w.`windDir`)) AS windDir_old_wh_conflicts, SUM(NOT (o.`windDir` <=> z.`windDir`)) AS windDir_old_euold_conflicts, SUM(NOT (o.`barometer` <=> w.`barometer`)) AS barometer_old_wh_conflicts, SUM(NOT (o.`barometer` <=> z.`barometer`)) AS barometer_old_euold_conflicts, SUM(NOT (o.`pressure` <=> w.`pressure`)) AS pressure_old_wh_conflicts, SUM(NOT (o.`pressure` <=> z.`pressure`)) AS pressure_old_euold_conflicts, SUM(NOT (o.`altimeter` <=> w.`altimeter`)) AS altimeter_old_wh_conflicts, SUM(NOT (o.`altimeter` <=> z.`altimeter`)) AS altimeter_old_euold_conflicts, SUM(o.`usUnits`<>w.`usUnits`) AS usUnits_old_wh_conflicts, SUM(o.`interval`<>w.`interval`) AS interval_old_wh_conflicts, SUM(o.`usUnits`<>z.`usUnits`) AS usUnits_old_euold_conflicts, SUM(o.`interval`<>z.`interval`) AS interval_old_euold_conflicts FROM (SELECT CASE WHEN `dateTime`>1238346600 AND `dateTime`<1238353200 THEN 1 WHEN `dateTime`>1238841000 AND `dateTime`<1238851500 THEN 2 WHEN `dateTime`>1239094200 AND `dateTime`<1239100200 THEN 3 WHEN `dateTime`>1239736800 AND `dateTime`<1239742800 THEN 4 WHEN `dateTime`>1239798600 AND `dateTime`<1239805500 THEN 5 WHEN `dateTime`>1240390500 AND `dateTime`<1240397400 THEN 6 WHEN `dateTime`>1244473500 AND `dateTime`<1244479800 THEN 7 WHEN `dateTime`>1245931200 AND `dateTime`<1245942300 THEN 8 WHEN `dateTime`>1246052100 AND `dateTime`<1246064700 THEN 9 WHEN `dateTime`>1246365300 AND `dateTime`<1246373700 THEN 10 WHEN `dateTime`>1246542000 AND `dateTime`<1246555200 THEN 11 WHEN `dateTime`>1246561200 AND `dateTime`<1246569300 THEN 12 WHEN `dateTime`>1246987200 AND `dateTime`<1246999500 THEN 13 WHEN `dateTime`>1247921400 AND `dateTime`<1247932500 THEN 14 WHEN `dateTime`>1250055900 AND `dateTime`<1250082000 THEN 15 WHEN `dateTime`>1251234900 AND `dateTime`<1251254400 THEN 16 WHEN `dateTime`>1251483300 AND `dateTime`<1251487800 THEN 17 WHEN `dateTime`>1252502700 AND `dateTime`<1252509300 THEN 18 WHEN `dateTime`>1256155500 AND `dateTime`<1256167500 THEN 19 WHEN `dateTime`>1256167500 AND `dateTime`<1256183700 THEN 20 WHEN `dateTime`>1256308800 AND `dateTime`<1256315700 THEN 21 WHEN `dateTime`>1256999700 AND `dateTime`<1257006600 THEN 22 WHEN `dateTime`>1257944700 AND `dateTime`<1257952500 THEN 23 WHEN `dateTime`>1260950700 AND `dateTime`<1260960600 THEN 24 WHEN `dateTime`>1261086600 AND `dateTime`<1261092900 THEN 25 WHEN `dateTime`>1261992300 AND `dateTime`<1262015700 THEN 26 ELSE NULL END AS gap_id, `dateTime`, `outTemp`, `outHumidity`, `rain`, `rainRate`, `windSpeed`, `windGust`, `windDir`, `barometer`, `pressure`, `altimeter`, `usUnits`, `interval` FROM `old_weewx`.`archive` WHERE (`dateTime`>1238346600 AND `dateTime`<1238353200) OR (`dateTime`>1238841000 AND `dateTime`<1238851500) OR (`dateTime`>1239094200 AND `dateTime`<1239100200) OR (`dateTime`>1239736800 AND `dateTime`<1239742800) OR (`dateTime`>1239798600 AND `dateTime`<1239805500) OR (`dateTime`>1240390500 AND `dateTime`<1240397400) OR (`dateTime`>1244473500 AND `dateTime`<1244479800) OR (`dateTime`>1245931200 AND `dateTime`<1245942300) OR (`dateTime`>1246052100 AND `dateTime`<1246064700) OR (`dateTime`>1246365300 AND `dateTime`<1246373700) OR (`dateTime`>1246542000 AND `dateTime`<1246555200) OR (`dateTime`>1246561200 AND `dateTime`<1246569300) OR (`dateTime`>1246987200 AND `dateTime`<1246999500) OR (`dateTime`>1247921400 AND `dateTime`<1247932500) OR (`dateTime`>1250055900 AND `dateTime`<1250082000) OR (`dateTime`>1251234900 AND `dateTime`<1251254400) OR (`dateTime`>1251483300 AND `dateTime`<1251487800) OR (`dateTime`>1252502700 AND `dateTime`<1252509300) OR (`dateTime`>1256155500 AND `dateTime`<1256167500) OR (`dateTime`>1256167500 AND `dateTime`<1256183700) OR (`dateTime`>1256308800 AND `dateTime`<1256315700) OR (`dateTime`>1256999700 AND `dateTime`<1257006600) OR (`dateTime`>1257944700 AND `dateTime`<1257952500) OR (`dateTime`>1260950700 AND `dateTime`<1260960600) OR (`dateTime`>1261086600 AND `dateTime`<1261092900) OR (`dateTime`>1261992300 AND `dateTime`<1262015700)) o LEFT JOIN `weewx_WH1080`.`archive` w ON w.`dateTime`=o.`dateTime` LEFT JOIN `pocasi-loucka.eu_old`.`archive` z ON z.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` r ON r.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` rp ON rp.`dateTime`=(o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0)) WHERE o.gap_id IS NOT NULL GROUP BY o.gap_id ORDER BY o.gap_id;
